<script>document.addEventListener('DOMContentLoaded',()=>{const shell=document.querySelector('.sidebar-shell');if(shell){const toggle=shell.querySelector('.sidebar-mobile-toggle'),close=shell.querySelector('.sidebar-close'),overlay=shell.querySelector('.sidebar-overlay'),setOpen=open=>{shell.classList.toggle('is-open',open);toggle?.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':'';};toggle?.addEventListener('click',()=>setOpen(true));close?.addEventListener('click',()=>setOpen(false));overlay?.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',event=>{if(event.key==='Escape')setOpen(false);});}const modal=document.getElementById('logout-modal'),trigger=document.getElementById('logout-trigger'),cancel=document.getElementById('logout-cancel');if(modal&&trigger&&cancel){const open=()=>{modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');cancel.focus();};const close=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');trigger.focus();};trigger.addEventListener('click',open);cancel.addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('is-open'))close();});}});</script>
